use std::collections::HashMap;

# [derive (Subcommand)] enum Commands { # [doc = " Reflect over AST in a directory"] Reflect { # [doc = " Directory to reflect over"] # [arg (short , long)] dir : String , # [doc = " Probe configuration file"] # [arg (short , long)] probes : Option < String > , # [doc = " Output directory for transformed files"] # [arg (short , long)] output : Option < String > , # [doc = " Verbose output"] # [arg (short , long)] verbose : bool , } , # [doc = " Generate example probe configuration"] GenProbes { # [doc = " Output file for probe configuration"] # [arg (short , long , default_value = "ast_probes.json")] output : String , } , # [doc = " List available probe types and actions"] ListTypes , # [doc = " Analyze AST patterns in directory"] Analyze { # [doc = " Directory to analyze"] # [arg (short , long)] dir : String , # [doc = " Generate probes based on analysis"] # [arg (short , long)] generate : bool , } , }